### 知识图谱可视化

```typescript
// src/ui/components/GraphView/ForceGraph.tsx

interface GraphNode {
  id: string;           // "auth/jwt-config"
  label: string;        // "JWT配置"
  category: string;     // "auth"
  status: string;       // "published" | "deprecated" | "archived"
  confidence: string;   // "high" | "medium" | "low"
  inDegree: number;     // 被引用次数
  outDegree: number;    // 引用次数
  // 可视化属性
  size: number;         // 与被引用次数成正比
  color: string;        // category → 颜色映射
}

interface GraphEdge {
  source: string;       // "auth/jwt-config"
  target: string;       // "auth/token-rotation"
  weight: number;       // 0.0-1.0
  label?: string;       // 可选边标签
}

function ForceGraph({ nodes, edges, onNodeClick }) {
  useEffect(() => {
    const cy = cytoscape({
      container: containerRef.current,
      elements: [
        ...nodes.map(n => ({
          data: { id: n.id, label: n.label, ...n },
        })),
        ...edges.map((e, i) => ({
          data: {
            id: `e${i}`,
            source: e.source,
            target: e.target,
            weight: e.weight,
          },
        })),
      ],
      style: [
        {
          selector: 'node',
          style: {
            'label': 'data(label)',
            'width': 'mapData(size, 5, 80, 20, 80)',
            'height': 'mapData(size, 5, 80, 20, 80)',
            'background-color': 'data(color)',
            'border-width': 2,
            'border-color': '#fff',
            'font-size': '10px',
            'text-valign': 'bottom',
            'text-halign': 'center',
            'text-margin-y': 8,
          },
        },
        {
          selector: 'node[status="deprecated"]',
          style: { 'border-color': '#f59e0b', 'border-style': 'dashed' },
        },
        {
          selector: 'node[status="archived"]',
          style: { 'opacity': 0.4 },
        },
        {
          selector: 'edge',
          style: {
            'width': 'mapData(weight, 0, 1, 1, 5)',
            'line-color': '#94a3b8',
            'target-arrow-color': '#94a3b8',
            'target-arrow-shape': 'triangle',
            'curve-style': 'bezier',
            'opacity': 0.6,
          },
        },
      ],
      layout: {
        name: 'cose',           // 力导向布局
        animate: true,
        nodeRepulsion: 8000,
        idealEdgeLength: 120,
        gravity: 0.3,
      },
    });

    cy.on('click', 'node', (evt) => {
      const nodeId = evt.target.id();
      onNodeClick(nodeId);
    });

    // 悬停时高亮邻居节点
    cy.on('mouseover', 'node', (evt) => {
      const node = evt.target;
      const neighborhood = node.closedNeighborhood();
      cy.elements().difference(neighborhood).addClass('dimmed');
    });
    cy.on('mouseout', 'node', () => {
      cy.elements().removeClass('dimmed');
    });

    return () => cy.destroy();
  }, [nodes, edges]);

  return <div ref={containerRef} style={{ width: '100%', height: '600px' }} />;
}
```

